files.src/PumpStation.st:
(* Pump station: two instances of the project function block PumpCtl, each with its own memory. *)
PROGRAM PumpStation
VAR_INPUT
    Start1 AT %I0.0 : BOOL;
    Start2 AT %I0.1 : BOOL;
    Stop AT %I0.2 : BOOL;
    Ready AT %I0.3 : BOOL;
END_VAR
VAR_OUTPUT
    Pump1 AT %Q0.0 : BOOL;
    Pump2 AT %Q0.1 : BOOL;
END_VAR
VAR
    Pump1Ctl : PumpCtl;
    Pump2Ctl : PumpCtl;
END_VAR

Pump1Ctl(Start := Start1, Stop := Stop, Ready := Ready);
Pump1 := Pump1Ctl.Run;
Pump2Ctl(Start := Start2, Stop := Stop, Ready := Ready);
Pump2 := Pump2Ctl.Run;
END_PROGRAM

